mkdir -p /app/output && cat > /app/output/index.html <<'HTML'
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Fresh Pantry — Discover Everyday Deliciousness</title>
  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
  <link href="https://fonts.googleapis.com/css2?family=Nunito:wght@600;700;800&family=Inter:wght@400;500;600;700&display=swap" rel="stylesheet">
  <style>
    :root {
      --cream: #fffaf0;
      --soft-cream: #fffdf7;
      --green-900: #1f4d3b;
      --green-700: #2f7a55;
      --green-500: #4fb37a;
      --green-300: #b8e7cd;
      --yellow: #ffd65a;
      --terracotta: #e07a5f;
      --text: #26332c;
      --muted: #607267;
      --card: #ffffff;
      --shadow: 0 10px 30px rgba(31, 77, 59, 0.12);
      --radius-lg: 22px;
      --radius-md: 16px;
    }

    * { box-sizing: border-box; }
    html, body { margin: 0; padding: 0; }
    body {
      font-family: 'Inter', system-ui, -apple-system, sans-serif;
      color: var(--text);
      background: linear-gradient(180deg, var(--soft-cream), var(--cream));
      line-height: 1.55;
    }

    .container {
      width: min(1120px, calc(100% - 2rem));
      margin: 0 auto;
    }

    h1, h2, h3, h4, .brand, .stat-value {
      font-family: 'Nunito', 'Inter', sans-serif;
      letter-spacing: 0.2px;
      margin: 0;
    }

    a { color: inherit; text-decoration: none; }

    header {
      position: sticky;
      top: 0;
      z-index: 10;
      background: rgba(255, 250, 240, 0.9);
      backdrop-filter: blur(10px);
      border-bottom: 1px solid rgba(47, 122, 85, 0.08);
    }

    .nav-wrap {
      display: flex;
      align-items: center;
      justify-content: space-between;
      padding: 0.9rem 0;
      gap: 1rem;
    }

    .brand {
      font-size: 1.45rem;
      font-weight: 800;
      color: var(--green-900);
      display: flex;
      align-items: center;
      gap: 0.45rem;
    }

    .brand-badge {
      width: 34px;
      height: 34px;
      border-radius: 10px;
      background: linear-gradient(145deg, var(--green-500), var(--green-700));
      color: white;
      display: grid;
      place-items: center;
      font-size: 1rem;
    }

    nav {
      display: flex;
      gap: 1.2rem;
      font-weight: 600;
      color: var(--green-900);
      flex-wrap: wrap;
      justify-content: flex-end;
    }

    nav a {
      padding: 0.35rem 0.55rem;
      border-radius: 999px;
      transition: background-color .2s ease;
    }

    nav a:hover { background: rgba(79, 179, 122, 0.14); }

    .hero {
      padding: 4rem 0 2.8rem;
      display: grid;
      grid-template-columns: 1.15fr 1fr;
      align-items: center;
      gap: 2rem;
    }

    .pill {
      display: inline-block;
      padding: 0.4rem 0.75rem;
      border-radius: 999px;
      font-weight: 700;
      color: var(--green-900);
      background: var(--green-300);
      margin-bottom: 0.9rem;
      font-size: 0.9rem;
    }

    .hero h1 {
      font-size: clamp(2rem, 5vw, 3.35rem);
      line-height: 1.1;
      color: var(--green-900);
      margin-bottom: 0.9rem;
    }

    .hero p {
      color: var(--muted);
      font-size: 1.06rem;
      margin: 0 0 1.4rem;
      max-width: 54ch;
    }

    .hero-actions {
      display: flex;
      gap: 0.75rem;
      flex-wrap: wrap;
    }

    .btn {
      border: none;
      border-radius: 12px;
      padding: 0.75rem 1.05rem;
      font-weight: 700;
      cursor: pointer;
      transition: transform 0.15s ease, box-shadow 0.2s ease;
      font-family: inherit;
    }

    .btn-primary {
      background: var(--green-700);
      color: white;
      box-shadow: 0 8px 18px rgba(47, 122, 85, 0.25);
    }

    .btn-secondary {
      background: #fff;
      color: var(--green-900);
      border: 1px solid rgba(47, 122, 85, 0.2);
    }

    .btn:hover { transform: translateY(-1px); }

    .hero-visual {
      border-radius: var(--radius-lg);
      overflow: hidden;
      box-shadow: var(--shadow);
      min-height: 320px;
      background: #f4f8ef;
    }

    .hero-visual img {
      width: 100%;
      height: 100%;
      object-fit: cover;
      display: block;
    }

    .section {
      padding: 2.8rem 0;
    }

    .section-title {
      font-size: clamp(1.45rem, 2.7vw, 2.1rem);
      color: var(--green-900);
      margin-bottom: 0.45rem;
    }

    .section-subtitle {
      margin: 0 0 1.2rem;
      color: var(--muted);
    }

    .stats-banner {
      background: linear-gradient(120deg, var(--green-900), var(--green-700));
      color: #fff;
      border-radius: var(--radius-lg);
      padding: 1.2rem;
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 0.9rem;
      box-shadow: var(--shadow);
    }

    .stat-item {
      background: rgba(255, 255, 255, 0.1);
      border: 1px solid rgba(255, 255, 255, 0.15);
      border-radius: var(--radius-md);
      padding: 0.95rem;
      text-align: center;
    }

    .stat-value {
      font-size: clamp(1.35rem, 3.2vw, 2rem);
      font-weight: 800;
      margin-bottom: 0.15rem;
    }

    .carousel-shell {
      position: relative;
    }

    .carousel-track {
      display: flex;
      gap: 1rem;
      overflow-x: auto;
      scroll-behavior: smooth;
      padding: 0.3rem 0.1rem 0.4rem;
      scrollbar-width: none;
    }

    .carousel-track::-webkit-scrollbar { display: none; }

    .product-card {
      flex: 0 0 calc((100% - 3rem) / 4);
      min-width: 230px;
      background: var(--card);
      border-radius: var(--radius-md);
      box-shadow: var(--shadow);
      overflow: hidden;
      border: 1px solid rgba(47, 122, 85, 0.1);
    }

    .product-card img {
      width: 100%;
      height: 155px;
      object-fit: cover;
    }

    .product-content { padding: 0.8rem; }
    .product-name { font-weight: 700; margin-bottom: 0.25rem; color: var(--green-900); }
    .product-price { color: var(--terracotta); font-weight: 700; }

    .carousel-controls {
      position: absolute;
      top: -3.2rem;
      right: 0;
      display: flex;
      gap: 0.55rem;
    }

    .icon-btn {
      width: 40px;
      height: 40px;
      border-radius: 999px;
      border: 1px solid rgba(47, 122, 85, 0.2);
      background: #fff;
      color: var(--green-900);
      font-size: 1.1rem;
      cursor: pointer;
    }

    .seasonal-grid {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 1rem;
    }

    .seasonal-card {
      background: #fff;
      border-radius: var(--radius-md);
      overflow: hidden;
      box-shadow: var(--shadow);
      border: 1px solid rgba(47, 122, 85, 0.1);
    }

    .seasonal-card img { width: 100%; height: 170px; object-fit: cover; }
    .seasonal-body { padding: 0.85rem; }

    .category-grid {
      display: grid;
      grid-template-columns: repeat(5, 1fr);
      gap: 0.85rem;
    }

    .category-card {
      position: relative;
      border-radius: 18px;
      overflow: hidden;
      min-height: 165px;
      box-shadow: var(--shadow);
      transform: translateY(0) scale(1);
      transition: transform 0.25s ease;
      isolation: isolate;
    }

    .category-card img {
      width: 100%;
      height: 100%;
      object-fit: cover;
      display: block;
    }

    .category-overlay {
      position: absolute;
      inset: 0;
      background: linear-gradient(to top, rgba(31, 77, 59, 0.78), rgba(31, 77, 59, 0.15));
      color: #fff;
      display: flex;
      align-items: flex-end;
      justify-content: center;
      text-align: center;
      padding: 0.8rem;
      font-family: 'Nunito', sans-serif;
      font-weight: 700;
      letter-spacing: 0.2px;
    }

    .category-card:hover {
      transform: scale(1.03);
    }

    .store-box,
    .newsletter-box {
      background: #fff;
      border-radius: var(--radius-lg);
      padding: 1.2rem;
      box-shadow: var(--shadow);
      border: 1px solid rgba(47, 122, 85, 0.1);
    }

    .input-row {
      display: flex;
      gap: 0.6rem;
      flex-wrap: wrap;
      margin-top: 0.75rem;
    }

    input[type="text"], input[type="email"] {
      flex: 1;
      min-width: 220px;
      border: 1px solid rgba(47, 122, 85, 0.28);
      background: #fff;
      border-radius: 12px;
      padding: 0.75rem 0.85rem;
      font: inherit;
    }

    table {
      width: 100%;
      border-collapse: collapse;
      margin-top: 1rem;
      font-size: 0.95rem;
      overflow: hidden;
      border-radius: 12px;
    }

    th, td {
      padding: 0.65rem;
      text-align: left;
      border-bottom: 1px solid #edf2eb;
    }

    th {
      background: #f4fbf7;
      color: var(--green-900);
    }

    .hidden { display: none; }

    .confirmation {
      margin-top: 0.75rem;
      color: var(--green-700);
      font-weight: 600;
    }

    footer {
      margin-top: 2.8rem;
      background: #173d2f;
      color: #ecf6f0;
      padding: 2rem 0 1.5rem;
    }

    .footer-grid {
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 1rem;
      margin-bottom: 1rem;
    }

    .footer-title {
      color: #fff;
      font-family: 'Nunito', sans-serif;
      margin-bottom: 0.45rem;
    }

    .footer-col a {
      display: inline-block;
      margin: 0.2rem 0;
      color: #d0e4d8;
      font-size: 0.95rem;
    }

    .footer-note {
      border-top: 1px solid rgba(255, 255, 255, 0.16);
      padding-top: 0.8rem;
      color: #d4e8dd;
      font-size: 0.92rem;
    }

    @media (max-width: 980px) {
      .hero { grid-template-columns: 1fr; }
      .stats-banner { grid-template-columns: repeat(2, 1fr); }
      .seasonal-grid { grid-template-columns: 1fr 1fr; }
      .category-grid { grid-template-columns: repeat(3, 1fr); }
      .footer-grid { grid-template-columns: repeat(2, 1fr); }
    }

    @media (max-width: 680px) {
      .section { padding: 2.2rem 0; }
      .stats-banner { grid-template-columns: 1fr; }
      .seasonal-grid { grid-template-columns: 1fr; }
      .category-grid { grid-template-columns: repeat(2, 1fr); }
      .carousel-controls { position: static; margin-bottom: 0.6rem; }
      .footer-grid { grid-template-columns: 1fr; }
      nav { gap: 0.5rem; }
    }
  </style>
</head>
<body>
