    const carousel = document.getElementById('productCarousel');
    const prevBtn = document.getElementById('carouselPrev');
    const nextBtn = document.getElementById('carouselNext');

    function scrollCarousel(direction) {
      const card = carousel.querySelector('.product-card');
      const scrollAmount = card ? (card.getBoundingClientRect().width + 16) * 1.1 : 260;
      carousel.scrollBy({ left: direction * scrollAmount, behavior: 'smooth' });
    }

    prevBtn.addEventListener('click', () => scrollCarousel(-1));
    nextBtn.addEventListener('click', () => scrollCarousel(1));

    const zipInput = document.getElementById('zipInput');
    const searchStores = document.getElementById('searchStores');
    const storeResults = document.getElementById('storeResults');

    searchStores.addEventListener('click', () => {
      const value = zipInput.value.trim();
      if (value.length > 0) {
        storeResults.classList.remove('hidden');
      } else {
        storeResults.classList.add('hidden');
      }
    });

    const emailInput = document.getElementById('emailInput');
    const subscribeBtn = document.getElementById('subscribeBtn');
    const newsletterConfirm = document.getElementById('newsletterConfirm');

    subscribeBtn.addEventListener('click', () => {
      const email = emailInput.value.trim();
      const basicEmail = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
      if (basicEmail.test(email)) {
        newsletterConfirm.classList.remove('hidden');
      } else {
        newsletterConfirm.classList.add('hidden');
      }
    });
  </script>
